import java.util.*;

class BruteForceCentroid {
    int findCentroid(int n, int[][] edges) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        for (int removed = 0; removed < n; removed++) {
            int largest = largestComponent(n, adj, removed);
            if (largest <= n / 2) return removed;
        }
        return -1;   // unreachable for a valid tree
    }

    private int largestComponent(int n, List<List<Integer>> adj, int removed) {
        boolean[] seen = new boolean[n];
        seen[removed] = true;
        int largest = 0;
        for (int start = 0; start < n; start++) {
            if (seen[start]) continue;
            int count = 0;
            Deque<Integer> stack = new ArrayDeque<>();
            stack.push(start); seen[start] = true;
            while (!stack.isEmpty()) {
                int node = stack.pop(); count++;
                for (int nx : adj.get(node)) if (!seen[nx]) { seen[nx] = true; stack.push(nx); }
            }
            largest = Math.max(largest, count);
        }
        return largest;
    }
}

