from collections import defaultdict

class BruteForceCentroid:
    def find_centroid(self, n: int, edges: list[tuple[int, int]]) -> int:
        adj = defaultdict(list)
        for a, b in edges:
            adj[a].append(b)
            adj[b].append(a)
        for removed in range(n):
            if self._largest_component(n, adj, removed) <= n // 2:
                return removed
        return -1

    def _largest_component(self, n, adj, removed):
        seen = [False] * n
        seen[removed] = True
        largest = 0
        for start in range(n):
            if seen[start]:
                continue
            count = 0
            stack = [start]
            seen[start] = True
            while stack:
                node = stack.pop()
                count += 1
                for nx in adj[node]:
                    if not seen[nx]:
                        seen[nx] = True
                        stack.append(nx)
            largest = max(largest, count)
        return largest

