import java.util.*;

class Centroid {
    int findCentroid(int n, int[][] edges) {
        if (n == 1) return 0;
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }

        int[] size = new int[n];
        int[] parent = new int[n];
        int root = 0;
        // Iterative DFS: discovery order then reverse for post-order sizes.
        int[] order = new int[n]; int idx = 0;
        boolean[] seen = new boolean[n];
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(root); parent[root] = root; seen[root] = true;
        while (!stack.isEmpty()) {
            int node = stack.pop(); order[idx++] = node;
            for (int nx : adj.get(node)) if (!seen[nx]) { seen[nx] = true; parent[nx] = node; stack.push(nx); }
        }
        for (int i = n - 1; i >= 0; i--) {        // children before parents
            int node = order[i];
            size[node] = 1;
            for (int c : adj.get(node)) if (c != parent[node]) size[node] += size[c];
        }
        // Evaluate the largest piece for each node.
        for (int node = 0; node < n; node++) {
            int largest = n - size[node];          // the part ABOVE node
            for (int c : adj.get(node)) if (c != parent[node]) {
                largest = Math.max(largest, size[c]);
            }
            if (largest <= n / 2) return node;
        }
        return -1;   // unreachable for a valid tree
    }
}

