from collections import defaultdict

class Centroid:
    def find_centroid(self, n: int, edges: list[tuple[int, int]]) -> int:
        if n == 1:
            return 0
        adj = defaultdict(list)
        for a, b in edges:
            adj[a].append(b)
            adj[b].append(a)

        size = [0] * n
        parent = [0] * n
        root = 0
        order = []
        seen = [False] * n
        stack = [root]
        seen[root] = True
        while stack:                          # discovery order
            node = stack.pop()
            order.append(node)
            for nx in adj[node]:
                if not seen[nx]:
                    seen[nx] = True
                    parent[nx] = node
                    stack.append(nx)
        for node in reversed(order):          # children before parents
            size[node] = 1
            for c in adj[node]:
                if c != parent[node]:
                    size[node] += size[c]
        for node in range(n):
            largest = n - size[node]          # the part ABOVE node
            for c in adj[node]:
                if c != parent[node]:
                    largest = max(largest, size[c])
            if largest <= n // 2:
                return node
        return -1

